        if (!comp_v_pos) comp_pos_v = g_keys[pos] < v;
        if (!comp_v_pos && comp_pos_v && (after == g_n || v < g_keys[after])) { ++g_hinted; return insert_at(after, v); }
        if (comp_v_pos == comp_pos_v) return pos;
        return insert_unique_plain(v);
    }
