    Socket* Host;
    std::string Hostname;
    unsigned short Port;
    std::string ProxyHost;
    unsigned long ProxyPort;
    int Open()
    {
        if (Hostname == "")
            return 1;
        Host = new Socket;
        Address remote;
        if (ProxyHost != "")
            remote = Address(ProxyHost, (unsigned short)ProxyPort);
        else
            remote = Address(Hostname, Port);
        Address local(std::string("ANY"), 0);
        if (Host->Open(remote, local, true))
            return 0;
        return 3;
    }
